# ====================================================================== dtypes (session 1)

# from mission 08 — finished: read it, use it, do not change it
def to_uint8(a):
    """Any array of numbers → a uint8 picture: round to the NEAREST integer, keep 0..255 (values below 0
    become 0, above 255 become 255), then convert. Never wraps around (300 must not become 44).

    Input: a numpy array of any dtype and shape. Returns a uint8 array of the same shape.
    Example: to_uint8(np.array([-7.2, 0.4, 99.5, 254.6, 300.0])) → array([0, 0, 100, 255, 255], dtype=uint8)
             (99.5 → 100 and 0.5 → 0: numpy rounds a half to the even neighbour)
    """
    return np.clip(np.rint(np.asarray(a, dtype=np.float64)), 0, 255).astype(np.uint8)


# from mission 08 — finished: read it, use it, do not change it
def to_float01(a):
    """An image → float32 values in [0, 1]. An INTEGER image is divided by the largest value its dtype can
    hold (255 for uint8, 65 535 for uint16), so 0 stays 0 and the dtype's maximum becomes 1.0. A float
    image is assumed to be in [0, 1] already and is only converted to float32. Any other dtype (bool,
    complex, text) raises ValueError.

    Returns a float32 array of the same shape.
    Example: to_float01(np.array([0, 51, 255], np.uint8)) → array([0.0, 0.2, 1.0], dtype=float32)
             to_float01(np.array([0, 13107, 65535], np.uint16)) → array([0.0, 0.2, 1.0], dtype=float32)
    """
    a = np.asarray(a)
    if a.dtype == np.bool_ or not (np.issubdtype(a.dtype, np.integer) or np.issubdtype(a.dtype, np.floating)):
        raise ValueError(f"to_float01 needs an integer or float image, got dtype {a.dtype}")
    if np.issubdtype(a.dtype, np.integer):
        return (a.astype(np.float64) / float(np.iinfo(a.dtype).max)).astype(np.float32)
    return a.astype(np.float32)


# from mission 08 — finished: read it, use it, do not change it
def to_gray(img):
    """Grey uint8 (H, W) from a BGR uint8 image, with the luminance Y = 0.299 R + 0.587 G + 0.114 B
    (ITU-R BT.601, what cv2.cvtColor(img, cv2.COLOR_BGR2GRAY) uses, ± 1 for rounding).
    A picture that is already grey (2 dimensions) is returned unchanged.

    Example: to_gray(np.array([[[255, 0, 0], [0, 0, 255]]], np.uint8)) → array([[29, 76]], dtype=uint8)
             (pure blue, pure red)
    """
    # from mission 08 — finished: read it, use it, do not change it
    img = np.asarray(img)
    if img.ndim == 2:
        return img
    f = img.astype(np.float32)
    return to_uint8(0.114 * f[..., 0] + 0.587 * f[..., 1] + 0.299 * f[..., 2])


