def histogram(gray):
    """The 256 counts of a grey uint8 picture: h[v] = how many pixels have the value v.

    Example: histogram(np.array([[0, 0], [3, 255]], np.uint8))[[0, 3, 255]] → array([2, 1, 1])
    """
    # from mission 08 — finished: read it, use it, do not change it
    return np.bincount(np.asarray(gray, np.uint8).ravel(), minlength=256)


# from mission 08 — finished: read it, use it, do not change it
def normalise(gray):
    """Min–max stretch of a grey image of ANY numeric dtype (uint8, uint16, float) to a uint8 picture:
    the darkest pixel becomes 0, the brightest 255, everything in between in proportion (rounded).
    A uniform image (darkest = brightest) gives all zeros (nothing to stretch, and no division by 0).

    Returns a uint8 array of the same shape.
    Example: normalise(np.array([[7200, 7800], [8400, 7500]], np.uint16)) → array([[0, 128], [255, 64]], dtype=uint8)
             (a 16-bit thermal patch: 7 200 → 0, 8 400 → 255)
    """
    g = np.asarray(gray, dtype=np.float64)
    lo, hi = float(g.min()), float(g.max())
    if hi == lo:
        return np.zeros(g.shape, np.uint8)
    return to_uint8((g - lo) / (hi - lo) * 255.0)


# ====================================================================== filters (session 1)

# from mission 08 — finished: read it, use it, do not change it
def convolve2d(img, k):
    """True 2-D convolution of a grey image with a small kernel: out(y, x) = Σ k(i, j) · img(y − i, x − j)
    for i, j from −r to r (the kernel is FLIPPED, lesson §4). Same size as img. Near the border the
    image is mirrored without repeating the edge pixel ("reflect 101": … c b | a b c …), as OpenCV does.

    Inputs: img (H, W), any numeric dtype; k a 2-D kernel with an ODD number of rows and of columns
    (else ValueError). Returns float32 (H, W).
    Example: convolve2d(np.array([[0.0, 0.0, 3.0, 6.0, 6.0]]), np.array([[1.0, 0.0, -1.0]]))
             → array([[0.0, 3.0, 6.0, 3.0, 0.0]], dtype=float32)
             (with the flip, the kernel [1, 0, −1] gives img(x + 1) − img(x − 1): brighter to the right → positive)
    """
    k = np.asarray(k, dtype=np.float64)
    if k.ndim != 2 or k.shape[0] % 2 == 0 or k.shape[1] % 2 == 0:
        raise ValueError(f"the kernel must be 2-D with odd sizes, got shape {k.shape}")
    f = np.asarray(img, dtype=np.float64)
    h, w = f.shape
    ry, rx = k.shape[0] // 2, k.shape[1] // 2
    p = np.pad(f, ((ry, ry), (rx, rx)), mode="reflect")
    flipped = k[::-1, ::-1]
    out = np.zeros((h, w), np.float64)
    for i in range(k.shape[0]):
        for j in range(k.shape[1]):
            out += flipped[i, j] * p[i:i + h, j:j + w]
    return out.astype(np.float32)


# from mission 08 — finished: read it, use it, do not change it
def gaussian_kernel(k, sigma):
    """A k × k Gaussian kernel (float32, its weights sum to 1). sigma ≤ 0 uses OpenCV's rule
    sigma = 0.3 · ((k − 1) · 0.5 − 1) + 0.8. Equal to the outer product of cv2.getGaussianKernel(k, sigma).

    Example: gaussian_kernel(3, 0.85)[1] → array([0.125, 0.2497, 0.125], dtype=float32) (the middle row, rounded)
    """
    # from mission 08 — finished: read it, use it, do not change it
    if sigma <= 0:
        sigma = 0.3 * ((k - 1) * 0.5 - 1) + 0.8
    x = np.arange(k, dtype=np.float64) - (k - 1) / 2.0
    g = np.exp(-x * x / (2.0 * sigma * sigma))
    g /= g.sum()
    return np.outer(g, g).astype(np.float32)


SOBEL_X = np.array([[1.0, 0.0, -1.0],
                    [2.0, 0.0, -2.0],
                    [1.0, 0.0, -1.0]]) / 8.0   # written for a TRUE convolution (already flipped); /8: course rule


# from mission 08 — finished: read it, use it, do not change it
def sobel(gray):
    """Brightness gradient (gx, gy) of a grey image, in grey levels per pixel: gx > 0 where the picture
    gets brighter to the RIGHT, gy > 0 where it gets brighter DOWNWARDS. Course rule (used in every
    mission): the Sobel sums are divided by 8, so a ramp that climbs 1 grey level per pixel gives exactly 1.
    Equal to cv2.Sobel(gray, cv2.CV_32F, 1, 0) / 8 and (0, 1) / 8. Uses YOUR convolve2d.

    Example: sobel(np.tile(np.arange(5.0), (5, 1)))[0][2] → array([0.0, 1.0, 1.0, 1.0, 0.0], dtype=float32)
             (the ramp 0, 1, 2, 3, 4: slope 1 inside; 0 at the borders, where the mirror makes a peak)
    """
    # from mission 08 — finished: read it, use it, do not change it
    return convolve2d(gray, SOBEL_X), convolve2d(gray, SOBEL_X.T)


