# from mission 08 — finished: read it, use it, do not change it
def affine_matrix(angle_deg, scale, centre):
    """The 2 × 3 affine matrix that turns a picture by angle_deg (positive = COUNTER-CLOCKWISE on the
    screen) and scales it by `scale`, both about the point centre = (cx, cy) in pixels, which stays where
    it is. Same matrix as cv2.getRotationMatrix2D(centre, angle_deg, scale) (note OpenCV's argument order).

    Returns a float64 array of shape (2, 3): [[a, b, tx], [c, d, ty]] maps (x, y) to
    (a·x + b·y + tx, c·x + d·y + ty).
    Example: affine_matrix(90.0, 2.0, (10.0, 0.0)) → [[0.0, 2.0, 10.0], [-2.0, 0.0, 20.0]] (to rounding)
    """
    cx, cy = float(centre[0]), float(centre[1])
    t = math.radians(angle_deg)
    a, b = scale * math.cos(t), scale * math.sin(t)
    return np.array([[a, b, (1.0 - a) * cx - b * cy],
                     [-b, a, b * cx + (1.0 - a) * cy]], dtype=np.float64)


# from mission 08 — finished: read it, use it, do not change it
def pixel_or_zero(img, ys, xs):
    """img[ys, xs] as float64 for integer index arrays ys, xs of the same shape (one pixel per pair, read
    all at once), and 0.0 where (ys, xs) falls outside the picture.

    Example: pixel_or_zero(np.array([[5, 6], [7, 8]]), np.array([0, 1, 2]), np.array([1, 0, 0])) → array([6., 7., 0.])
    """
    # from mission 08 — finished: read it, use it, do not change it
    img = np.asarray(img)
    h, w = img.shape[:2]
    ys, xs = np.asarray(ys), np.asarray(xs)
    inside = (ys >= 0) & (ys < h) & (xs >= 0) & (xs < w)
    vals = img[np.clip(ys, 0, h - 1), np.clip(xs, 0, w - 1)].astype(np.float64)
    return np.where(inside, vals, 0.0)


# from mission 08 — finished: read it, use it, do not change it
def warp_affine(img, M, size):
    """Apply the 2 × 3 affine M (it maps a SOURCE point to its DESTINATION) to a grey image by INVERSE
    mapping: for every destination pixel, find where it comes from in the source and read it there with
    BILINEAR interpolation (the 4 neighbours, weighted). Source pixels outside the picture count as 0.
    Same result as cv2.warpAffine(img, M, size) (default flags), to within about half a grey level on average
    (OpenCV rounds its interpolation weights).

    Inputs: img (H, W) grey, any numeric dtype; M (2, 3); size = (width, height) of the result, OpenCV's
    order. Returns float32 of shape (height, width).
    Example: warp_affine(np.array([[0.0, 10.0], [20.0, 30.0]]), np.array([[1.0, 0.0, -0.5], [0.0, 1.0, -0.5]]), (2, 2))
             → array([[15.0, 10.0], [12.5, 7.5]], dtype=float32)
             (shifted half a pixel up-left: each result is a blend, and the pixels past the edge count as 0)
    """
    M = np.asarray(M, dtype=np.float64)
    a_inv = np.linalg.inv(M[:, :2])
    tx, ty = M[0, 2], M[1, 2]
    w_out, h_out = int(size[0]), int(size[1])
    v, u = np.mgrid[0:h_out, 0:w_out].astype(np.float64)
    du, dv = u - tx, v - ty
    x = a_inv[0, 0] * du + a_inv[0, 1] * dv
    y = a_inv[1, 0] * du + a_inv[1, 1] * dv
    x0, y0 = np.floor(x).astype(np.int64), np.floor(y).astype(np.int64)
    fx, fy = x - x0, y - y0
    top = (1 - fx) * pixel_or_zero(img, y0, x0) + fx * pixel_or_zero(img, y0, x0 + 1)
    bottom = (1 - fx) * pixel_or_zero(img, y0 + 1, x0) + fx * pixel_or_zero(img, y0 + 1, x0 + 1)
    return ((1 - fy) * top + fy * bottom).astype(np.float32)


# from mission 08 — finished: read it, use it, do not change it
def like_map(photo, heading_deg, gsd_photo_m, gsd_map_m):
    """Make a downward drone photo comparable with a north-up map: grey, contrast stretched (normalise,
    BEFORE the warp), then ONE warp that turns it north-up and brings it to the map's metres per pixel.

    photo: (h, w, 3) BGR or (h, w) grey uint8. heading_deg: where the photo's TOP points, clockwise from
    north (90 = the top of the photo looks east). gsd_photo_m, gsd_map_m: metres on the ground per pixel.
    The result is a square of side round(hypot(w, h) · s) pixels, s = gsd_photo_m / gsd_map_m, big enough
    for every turn; the photo's centre point ((w − 1)/2, (h − 1)/2) lands on the result's centre point
    ((side − 1)/2, (side − 1)/2); pixels outside the photo's footprint are 0. Returns uint8.
    Example: like_map(np.zeros((40, 60), np.uint8), 0.0, 0.5, 1.0).shape → (36, 36)
             and with heading_deg=90.0, a bright mark at the top-centre of a photo lands on the result's
             middle row, right of its centre (east).
    """
    g = normalise(to_gray(photo))
    h, w = g.shape
    s = gsd_photo_m / gsd_map_m
    side = int(round(math.hypot(w, h) * s))
    c_in = ((w - 1) / 2.0, (h - 1) / 2.0)
    c_out = (side - 1) / 2.0
    M = affine_matrix(-heading_deg, s, c_in)
    M[0, 2] += c_out - c_in[0]
    M[1, 2] += c_out - c_in[1]
    return to_uint8(warp_affine(g, M, (side, side)))
